class Solution {
  public int reverse(int x) {
    int y = 0;
    while (x != 0) {
      int n = x % 10;
      if (y > Integer.MAX_VALUE / 10 || y < Integer.MIN_VALUE / 10) {
        return 0;
      }
      y = y * 10 + n;
      x /= 10;
    }
    return y;
  }
}

class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        n = abs(x)
        y = 0
        while n:
            y = y * 10 + n % 10
            n //= 10
        y *= sign
        if y < -2 ** 31 or y > 2 ** 31 - 1:
            return 0
        return y

impl Solution {
  pub fn reverse(x: i32) -> i32 {
    let mut ret = 0i32;
    let mut x_clone = x;
    while x_clone != 0 {
      let i = x_clone % 10;
      let x1 = ret.overflowing_mul(10);
      if x1.1 == true {
        return 0;
      }
      let x2 = x1.0.overflowing_add(i);
      if x2.1 == true {
        return 0;
      }
      ret = x2.0;
      x_clone = x_clone / 10;
    }

    ret
  }
}

const reverse = (x: number): number => {
  const sign = x < 0 ? -1 : 1;
  let n = Math.abs(x);
  let y = 0;

  while (n > 0) {
    y = y * 10 + (n % 10);
    n = Math.floor(n / 10);
  }

  y *= sign;
  if (y < -(2 ** 31) || y > 2 ** 31 - 1) return 0;
  return y;
};
